import type { Validated } from "@apple/cktool.core";
/**
 * Return the value of a validated object, if valid;
 * otherwise, throws the error from the validated object.
 *
 * @param validated The validated object to extract the value from.
 * @returns The value of a validated object, only if valid.
 */
export declare const getOrThrow: <E, T>(validated: Validated<E, T>) => T;
